const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,9);
const dt=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const addDays=(s,n)=>{let d=new Date((s||dt())+'T12:00:00');d.setDate(d.getDate()+n);return dateStr(d)};
const dateStr=(d)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const parse=(v)=>new Date((v||dt()).length===10?v+'T12:00:00':v);
const human=(v,opts={month:'short',day:'numeric'})=>{if(!v)return 'No date';try{return parse(v).toLocaleDateString('en-US',opts)}catch{return v}};
const clock=(n)=>{n=Math.max(0,Math.floor(n));return n>=3600?`${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`:`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`};
const PRIOR={high:'High',medium:'Medium',low:'Low',none:'None'};
const defaultData=()=>({version:1,lists:[{id:'inbox',name:'Inbox',color:'#6757e8'},{id:'study',name:'Personal Projects',color:'#30ac9c'},{id:'work',name:'Work',color:'#ed9c59'}],tasks:[{id:uid(),title:'Explore your new Do You workspace',status:'todo',priority:'medium',listId:'inbox',createdAt:Date.now(),dueAt:dt()+'T18:00',tags:['Welcome'],notes:'Open this task and explore priority, recurrence, subtasks, reminders and notes.',subtasks:[{id:uid(),title:'Try completing a subtask',done:false}],repeat:'none',repeatDays:1,reminder:0,estimate:25},{id:uid(),title:'Plan your week',status:'todo',priority:'high',listId:'study',createdAt:Date.now(),dueAt:addDays(dt(),1)+'T09:00',tags:['Planning'],notes:'This is an example. Edit or delete it anytime.',subtasks:[],repeat:'weekly',repeatDays:1,reminder:10,estimate:30}],habits:[{id:uid(),name:'Read for 15 minutes',emoji:'📖',goal:1,logs:{},freq:'daily',createdAt:Date.now()}],notes:[],goals:[],countdowns:[],focus:[],rules:[],settings:{theme:'light',accent:'#6757e8',compact:false,weekStartsMonday:true,focusMinutes:25,breakMinutes:5,notifications:true},focusRunning:null,deletedTasks:[]});
let data;try{data=JSON.parse(localStorage.getItem(KEY))||defaultData()}catch{data=defaultData()};
