data=normalizeData(data);
let timelineAnchor=dt();let page='today',view='list',drawer=false,modal='',editing=null,calMonth=new Date(),calSelected=dt(),listFilter='all',sortBy='due',searchQ='',focusMode='pomo',toastTimer,undo=null;
function normalizeData(d){
  const goodId=x=>typeof x==='string'&&/^[a-zA-Z0-9_-]{1,60}$/.test(x)?x:uid();
  const goodHex=x=>typeof x==='string'&&/^#[a-fA-F0-9]{6}$/.test(x)?x:'#6757e8';
  const str=(x,max=10000)=>typeof x==='string'?x.slice(0,max):String(x??'').slice(0,max);
  const cleanStep=x=>({id:goodId(x?.id),title:str(x?.title,220),done:!!x?.done});
  d.lists=d.lists.slice(0,2000).map(l=>({...l,id:goodId(l.id),name:str(l.name,150),color:goodHex(l.color)}));
  if(!d.lists.find(l=>l.id==='inbox'))d.lists.unshift({id:'inbox',name:'Inbox',color:'#6757e8'});
  d.tasks=d.tasks.slice(0,20000).map(t=>({...t,id:goodId(t.id),seriesId:t.seriesId?goodId(t.seriesId):undefined,title:str(t.title,300),notes:str(t.notes,30000),listId:goodId(t.listId||'inbox'),priority:['high','medium','low','none'].includes(t.priority)?t.priority:'none',status:['todo','doing','done'].includes(t.status)?t.status:'todo',dueAt:str(t.dueAt,20),startAt:str(t.startAt,20),deadline:str(t.deadline,12),reminder:Number.isFinite(Number(t.reminder))?Number(t.reminder):0,estimate:Math.max(0,Number(t.estimate)||0),repeat:['none','daily','weekdays','weekly','monthly','yearly','custom'].includes(t.repeat)?t.repeat:'none',repeatDays:Math.max(1,Number(t.repeatDays)||1),tags:Array.isArray(t.tags)?t.tags.slice(0,50).map(x=>str(x,80)):[],subtasks:Array.isArray(t.subtasks)?t.subtasks.slice(0,500).map(cleanStep):[]}));
  d.habits=d.habits.slice(0,1000).map(h=>({...h,id:goodId(h.id),name:str(h.name,150),emoji:str(h.emoji,8),goal:Math.max(1,Number(h.goal)||1),logs:Object.fromEntries(Object.entries((h.logs&&typeof h.logs==='object'&&!Array.isArray(h.logs))?h.logs:{}).filter(([date])=>/^\d{4}-\d{2}-\d{2}$/.test(date)).map(([date,v])=>[date,Math.max(0,Number(v)||0)]))}));
  d.notes=d.notes.slice(0,2000).map(n=>({...n,id:goodId(n.id),title:str(n.title,250),content:str(n.content,200000)}));
  d.goals=d.goals.slice(0,1000).map(g=>({...g,id:goodId(g.id),title:str(g.title,220),description:str(g.description,4000),deadline:str(g.deadline,12),steps:Array.isArray(g.steps)?g.steps.slice(0,300).map(cleanStep):[]}));
  d.countdowns=d.countdowns.slice(0,2000).map(c=>({...c,id:goodId(c.id),title:str(c.title,220),emoji:str(c.emoji,8),date:str(c.date,12),repeat:['none','monthly','yearly'].includes(c.repeat)?c.repeat:'none'}));
  d.focus=d.focus.slice(-50000).map(f=>({...f,id:goodId(f.id),minutes:Math.max(0,Number(f.minutes)||0),date:str(f.date,12),taskTitle:str(f.taskTitle,260)}));
  d.rules=d.rules.slice(0,500).map(r=>({...r,id:goodId(r.id),name:str(r.name,180),trigger:['overdue','due_today'].includes(r.trigger)?r.trigger:'overdue',action:['high','tag'].includes(r.action)?r.action:'high',enabled:!!r.enabled}));
  d.deletedTasks=d.deletedTasks.slice(-500).map(t=>({...t,id:goodId(t.id),title:str(t.title,300)}));
  d.settings=d.settings||{};d.settings.theme=d.settings.theme==='dark'?'dark':'light';d.settings.accent=goodHex(d.settings.accent);d.settings.compact=!!d.settings.compact;d.settings.weekStartsMonday=!!d.settings.weekStartsMonday;
  return d;
}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch(e){console.warn('Local storage unavailable or full',e)}syncReminders()}
function toast(message){let old=document.getElementById('toast');if(old)old.remove();let el=document.createElement('div');el.id='toast';el.className='toast';el.textContent=message;document.body.appendChild(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3200)}
function confirmDelete(message){return window.confirm(message)}
function listName(id){return data.lists.find(x=>x.id===id)?.name||'Inbox'}
const activeTasks=()=>data.tasks.filter(t=>t.status!=='done'&&t.status!=='archived');
function taskDay(t){return (t.dueAt||'').slice(0,10)}
function isOver(t){return !!t.dueAt&&t.status!=='done'&&parse(t.dueAt).getTime()<Date.now()}
function isToday(t){return taskDay(t)===dt()}
function taskSort(ts){let c=[...ts];if(sortBy==='priority')c.sort((a,b)=>({high:0,medium:1,low:2,none:3}[a.priority||'none']-({high:0,medium:1,low:2,none:3}[b.priority||'none'])));else if(sortBy==='title')c.sort((a,b)=>a.title.localeCompare(b.title));else c.sort((a,b)=>(a.dueAt||'9999').localeCompare(b.dueAt||'9999'));return c}
function showRail(v){drawer=v;document.querySelector('.app')?.classList.toggle('show-rail',v)}
const titles={today:'Today',inbox:'Inbox',tasks:'My Tasks',upcoming:'Upcoming',completed:'Completed',trash:'Trash & Recovery',calendar:'Calendar',matrix:'Priority Matrix',habits:'My Habits',focus:'Focus Time',countdown:'Countdown',notes:'My Notes',goals:'Goals & Milestones',stats:'Insights',automation:'Automations',settings:'Settings',lists:'My Lists',kanban:'Kanban Board',timeline:'Timeline',smart:'Smart Planner'};
